mapper.select:
SELECT rb.id AS id, rb.members_username AS members_username, rb.title AS title, rb.detail AS detail, rb.address AS address, rb.postcode AS postcode, rb.price AS price, rb.house_size AS house_size, rb.price_per AS price_per, rb.rent_start AS rent_start, rb.rent_until AS rent_until, rb.hashtags AS hashtags, rb.views AS views, rb.created_at AS created_at, rb.updated_at AS updated_at, rbi.url AS thumbnail_url FROM roomboards_bookmarks b JOIN roomboards rb ON b.roomboards_id = rb.id LEFT JOIN roomboards_images rbi ON rb.id = rbi.roomboards_id AND rbi.image_order = 0 WHERE b.members_username = #{username}
AND rb.id < #{cursorId}
ORDER BY rb.id DESC LIMIT #{pageSize};
